import{z as p,x as A,o,c as B,q as r,j as n,D as i,d as t,s as E,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"绝对位置编码","description":"","frontmatter":{"title":"绝对位置编码","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/absolute-position.md","filePath":"llm/absolute-position.md","lastUpdated":1791063341000}'),d={name:"llm/absolute-position.md"};function m(h,a,_,b,D,c){const s=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=r('<h1 id="绝对位置编码" tabindex="-1">绝对位置编码 <a class="header-anchor" href="#绝对位置编码" aria-label="Permalink to &quot;绝对位置编码&quot;">​</a></h1><div class="epigraph"><p>位置若被写成与内容相加的绝对坐标，训练长度就会变成一张不可见的边界。</p><footer>对照 Press 等的长度外推实验；相对位置见 Shaw，2018</footer></div><p><a href="/llm/linear-rnn-vs-attention">上一课</a>把线性 RNN 与注意力写成记忆接口的分工：前者固定状态做有损压缩，后者付 KV 做可寻址匹配。扫描里顺序已经在递推里；softmax 表对 token 置换等变，没有位置就分不清谁在谁前。缺口是注意力这一侧最直的注入：给下标 \\(i\\) 一个向量 \\(p_i\\)，与内容相加。正弦与可学习表都是这一绝对契约——坐标是「我是第 \\(i\\) 号」，不是「我离你 \\(i-j\\) 步」。本课只写契约本身，不重讲扫描与 KV 的分工。后课默认：选绝对方案等于同时选定了 \\(L_{\\max}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课把顺序留给了两种接口：扫描里递推已经有序，<a href="/llm/linear-rnn-vs-attention">注意力</a> 的表对 token 集合置换等变。没有位置信息时，\\(QK^\\top\\) 分不出「谁在谁前面」。注入的第一种办法，也是最初十年里最常见的办法，是<strong>绝对位置</strong>：给序列下标 \\(0,1,\\ldots,L-1\\) 各准备一个向量 \\(p_i\\)，与词嵌入相加（或拼接），此后注意力只看见已经带坐标的向量。</p><p><span class="marginnote">「对置换等变」是数学说法，翻译过来就是：把句子里的词任意打乱顺序，注意力的输出只是跟着换个位置，内部的数值关系完全不变——等于注意力天生看不见顺序。这就是为什么必须额外注入位置信息，否则「狗咬人」和「人咬狗」在它眼里是同一句话。</span></p><p>绝对的含义是：坐标附着在下标上，不附着在一对位置的差上。\\(p_{13}\\) 就是第 13 号位置的名字，与第 12 号、第 14 号的关系并不自动出现在参数里。模型若要学会「相对距离为 1」，必须从许多绝对坐标的组合里自己统计出来。</p><p><span class="marginnote">绝对位置可以是正弦公式，也可以是可学习表。本篇只讨论「绝对」这一契约；正弦与可学习表各有专文。</span></p><h3 id="等变被打破之后" tabindex="-1">等变被打破之后 <a class="header-anchor" href="#等变被打破之后" aria-label="Permalink to &quot;等变被打破之后&quot;">​</a></h3><p>加上 \\(p_i\\) 之后，注意力不再对置换等变，这是需要的。被一并打破的是对长度的同变性：训练时见过的下标集合成为表示的一部分。测试长度超过该集合，就是在问模型一个从未作为输入坐标出现过的名字。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>绝对位置编码的方法只有一层接口：</p> \\[x_i = e(w_i) + p_i, \\]<p>其中 \\(e(w_i)\\) 是 token 嵌入，\\(p_i \\in \\mathbb{R}^d\\) 由下标 \\(i\\) 唯一确定。\\(p_i\\) 的来源可以是闭式公式（正弦），也可以是嵌入表 \\(P \\in \\mathbb{R}^{L_{\\max} \\times d}\\) 的第 \\(i\\) 行。对注意力而言没有差别：进入 \\(W_Q, W_K, W_V\\) 的已经是绝对坐标化的向量。</p><p><span class="marginnote">数字实例：GPT-2 的可学习位置表是 \\(L_{\\max}=1024\\) 行、每行 \\(d=768\\) 维，整表约 \\(1024 \\times 768 \\approx 78.6\\) 万个参数。第 1025 号位置在这张表里查无此行——所以「扩窗」从来不是改个配置，而是要为新的行从头训练坐标。</span></p><p>有人把位置加在 QK 上而不是嵌入上，或做成偏置 \\(q^\\top k + b_{i}\\)，只要 \\(b\\) 依赖绝对下标 \\(i\\) 而不是 \\(i-j\\)，仍是绝对方案。Shaw 等（2018）的相对位置表示把可学习的 \\(a_{i-j}\\) 编进注意力 logits，那是对照项：同一套注意力，坐标从「我是第 \\(i\\) 号」换成「我离你 \\(i-j\\) 步」。</p><h3 id="训练长度写成容量" tabindex="-1">训练长度写成容量 <a class="header-anchor" href="#训练长度写成容量" aria-label="Permalink to &quot;训练长度写成容量&quot;">​</a></h3><p>可学习表的长度必须在训练前给定，\\(i \\ge L_{\\max}\\) 没有行。正弦公式表面上对任意 \\(i\\) 有定义，但频率是按训练分布里的 \\(i\\) 来用的：更大的 \\(i\\) 让高频分量进入从未见过的相位，注意力权重的几何会漂。两种绝对方案都把「多长算合法输入」写进了位置通道，只是一个写在表的形状里，一个写在相位的训练分布里。</p><p><span class="marginnote">初学者容易以为「正弦公式对任意 \\(i\\) 都有定义，所以天然能外推」。实际上模型用的是训练长度内那一段相位上的几何；超出之后，高频分量进入从未见过的相位区间，注意力权重整体漂移。对公式来说「有定义」，对模型来说「没被训练过」，这是两回事。</span></p>',19)),(o(),n(l,null,{default:i(()=>[E(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20Idx%5B%22%E4%B8%8B%E6%A0%87%20i%22%5D%20--%3E%20Abs%5B%22%E7%BB%9D%E5%AF%B9%E5%90%91%E9%87%8F%20p_i%22%5D%0A%20%20Tok%5B%22token%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20Add%5B%22%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20Abs%20--%3E%20Add%0A%20%20Add%20--%3E%20Attn%5B%22%E5%AF%B9%E4%BD%8D%E7%BD%AE%E6%97%A0%E6%84%9F%E7%9F%A5%E7%9A%84%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("h3",{id:"外推为什么失败",tabindex:"-1"},[t("外推为什么失败 "),e("a",{class:"header-anchor",href:"#外推为什么失败","aria-label":'Permalink to "外推为什么失败"'},"​")],-1)),a[5]||(a[5]=e("p",null,"Press、Smith、Lewis 在「短训长测」设定下系统比较了位置方案：用正弦或可学习绝对编码训练的 Transformer，输入一超过训练长度，困惑度急剧恶化。失败不是微调不够，是坐标系统本身——模型在 \\(i=512\\) 上学到的匹配，不能迁移到 \\(i=513\\)，因为 \\(p_{513}\\) 要么不存在，要么落在公式轨迹的未训练区段。",-1)),(o(),n(l,null,{default:i(()=>[E(s,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%E9%95%BF%E5%BA%A6%20Lmax%3D512%22%5D%20--%3E%20TAB%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E8%A1%A8%EF%BC%9A%E8%A1%8C%200-511%20%E5%B7%B2%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TAB%20--%3E%20OK%5B%22%E6%B5%8B%E8%AF%95%20i%20%E5%9C%A8%200-511%20%E5%86%85%EF%BC%9A%E6%AD%A3%E5%B8%B8%22%5D%0A%20%20Q%5B%22%E6%B5%8B%E8%AF%95%E8%BE%93%E5%85%A5%E9%95%BF%20600%22%5D%20--%3E%20NEW%5B%22i%3D512-599%EF%BC%9A%E6%9F%A5%E6%97%A0%E6%AD%A4%E8%A1%8C%22%5D%0A%20%20NEW%20--%3E%20FAIL%5B%22%E5%9B%B0%E6%83%91%E5%BA%A6%E6%80%A5%E5%89%A7%E6%81%B6%E5%8C%96%22%5D%0A%20%20SIN%5B%22%E6%AD%A3%E5%BC%A6%E5%85%AC%E5%BC%8F%EF%BC%9A%E4%BB%BB%E6%84%8F%20i%20%E6%9C%89%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20PHASE%5B%22%E5%A4%A7%20i%20%E7%9B%B8%E4%BD%8D%E8%90%BD%E5%9C%A8%E6%9C%AA%E8%AE%AD%E7%BB%83%E5%8C%BA%E6%AE%B5%22%5D%0A%20%20PHASE%20--%3E%20FAIL%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>相对位置或后续的 ALiBi、RoPE 把依赖改成 \\(i-j\\) 或旋转差，外推变成「未见过的距离」而不是「未见过的绝对名字」。绝对方案没有这条退路。把绝对表在测试时做线性插值、或把正弦的自变量缩放进训练区间，属于事后补丁，会改变已经学会的相位，通常伤害已训练长度上的质量。这正是「位置插值」一类工作要处理的对象；本篇只指出：补丁是在修绝对坐标的契约，不是绝对编码本来就会外推。</p><p><span class="marginnote">Geva、Press 等围绕前馈记忆与长度外推的讨论，把「绝对下标不可外推」写成了默认事实：不是某一层坏了，是坐标定义坏了。</span></p><h3 id="绝对坐标仍可能编码相对模式" tabindex="-1">绝对坐标仍可能编码相对模式 <a class="header-anchor" href="#绝对坐标仍可能编码相对模式" aria-label="Permalink to &quot;绝对坐标仍可能编码相对模式&quot;">​</a></h3><p>在训练长度之内，深度足够的注意力可以近似相对行为：某个头学会「看前一个位置」，等价于对许多 \\((p_i, p_{i-1})\\) 对拟合。这不矛盾。近似绑定在见过的下标上，换长度即失效。Vaswani 等曾论证正弦 PE 的线性组合能表示相对位移；论证是存在性的，不保证优化会找到它，更不保证位移超出训练范围仍成立。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>绝对位置的工程优点是简单：加一次，后面的层不用改。BERT、GPT-2 一类编码器/解码器在固定 \\(L_{\\max}\\) 内工作得很好。缺点在产品改上下文窗口的那一天全部兑现：扩窗等于换坐标系。</p><p>与相对 PE（Shaw，2018）相比，绝对方案把位置放在表示里，相对方案把位置放在 logits 里。后者多一次对 \\((i-j)\\) 的查表或计算，换来长度外推的可能性。现代 Decoder-only 模型几乎不再把可学习绝对表当默认，不是因为绝对在短序列上更差，是因为上下文长度已经成为必须改的超参。</p><p>另一条边界：绝对位置对「位置本身是特征」的任务仍然直接——例如已知列号的表格、固定模板。这类任务不要求外推到未见下标，绝对编码不是错误，是匹配问题的坐标系。不要把长文本 LLM 的教训无差别打到所有序列模型上。</p><p><span class="marginnote">NoPE（去掉显式位置）能在因果掩码里学到序，那是另一条路：用注意力可见性代替坐标。它对照的是「必须显式位置」，不是本篇的绝对相对之争。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>绝对位置编码把下标变成向量加到内容上，注意力本身仍无相对几何。正弦与可学习表都是这一契约的实现。Press 等的短训长测表明，该契约在训练长度之外会崩溃；Shaw（2018）的相对位置是直接对照：把 \\((i-j)\\) 写进注意力，而不是把 \\(i\\) 写进嵌入。后续的 RoPE、ALiBi 是相对（或偏置）路线的延续。选绝对方案时，等于同时选定了 \\(L_{\\max}\\) 为表示的一部分。</p>',11))])}const f=p(d,[["render",m]]);export{P as __pageData,f as default};
